// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceObservationSink {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceObservationSink = UniffiVTableCallbackInterfaceObservationSink(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeObservationSink.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface ObservationSink: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeObservationSink.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface ObservationSink: handle missing in uniffiClone")
            }
        },
        publish: { (
            uniffiHandle: UInt64,
            projection: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeObservationSink.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.publish(
                     projection: try FfiConverterTypeRuntimeProjection_lift(projection)
                )
            }


            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceObservationSink> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceObservationSink>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitObservationSink() {
    uniffi_bittery_client_bindings_fn_init_callback_vtable_observationsink(UniffiCallbackInterfaceObservationSink.vtablePtr)
}

